/**
 * WASOM UPFY v2.0 — lastest.min.js
 * Sistema de animação de contadores numéricos.
 * Autor: José Mbenga da Costa
 *
 * Uso no PHP:
 *   <span class="counter" data-valor="1250000" data-tipo="moeda"></span>
 *   <span class="counter" data-valor="94.5"    data-tipo="porcentagem"></span>
 *   <span class="counter" data-valor="3200"    data-tipo="contagem"></span>
 *   <span class="counter" data-valor="1.8734"  data-tipo="decimal"></span>
 *
 * Tipos disponíveis: moeda | porcentagem | contagem | decimal
 */

(function () {
  'use strict';

  // ── Formatadores ──────────────────────────────────────────────────────

  function formatarComEscala(valor, prefixo, casas) {
    prefixo = prefixo || '';
    casas   = (casas !== undefined) ? casas : 1;

    var escalas = [
      { limite: 1e12, sufixo: 'T', divisor: 1e12 },
      { limite: 1e9,  sufixo: 'B', divisor: 1e9  },
      { limite: 1e6,  sufixo: 'M', divisor: 1e6  },
      { limite: 1e3,  sufixo: 'mil', divisor: 1e3 }
    ];

    for (var i = 0; i < escalas.length; i++) {
      var e = escalas[i];
      if (Math.abs(valor) >= e.limite) {
        var red = (valor / e.divisor).toFixed(casas);
        return prefixo + (red.endsWith('.0')
          ? red.slice(0, -2) + e.sufixo
          : red.replace('.', ',') + e.sufixo);
      }
    }

    return prefixo + valor.toLocaleString('pt-AO');
  }

  function formatarMoeda(valor) {
    if (Math.abs(valor) >= 1000) {
      return formatarComEscala(valor, 'Kz ', 1);
    }
    return 'Kz ' + valor.toLocaleString('pt-AO', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    });
  }

  function formatarPorcentagem(valor) {
    return valor.toLocaleString('pt-AO', {
      minimumFractionDigits: 1,
      maximumFractionDigits: 2
    }) + '%';
  }

  function formatarDecimal(valor) {
    return valor.toLocaleString('pt-AO', {
      minimumFractionDigits: 1,
      maximumFractionDigits: 4
    });
  }

  function formatarContagem(valor) {
    return formatarComEscala(Math.round(valor), '', 1);
  }

  function aplicarFormato(el, valor) {
    var tipo = el.dataset.tipo;
    switch (tipo) {
      case 'moeda':       el.textContent = formatarMoeda(valor);       break;
      case 'porcentagem': el.textContent = formatarPorcentagem(valor); break;
      case 'decimal':     el.textContent = formatarDecimal(valor);     break;
      case 'contagem':    el.textContent = formatarContagem(valor);    break;
      default:            el.textContent = Math.round(valor);          break;
    }
  }

  // ── Animação de contador ──────────────────────────────────────────────

  function animarContador(el) {
    var valorFinal = parseFloat(el.dataset.valor);
    if (isNaN(valorFinal)) return;

    // Easing: ease-out cúbico
    function easeOut(t) { return 1 - Math.pow(1 - t, 3); }

    var duracao   = parseInt(el.dataset.duracao || '1800', 10);
    var startTime = null;

    function frame(ts) {
      if (!startTime) startTime = ts;
      var elapsed  = ts - startTime;
      var progresso = Math.min(elapsed / duracao, 1);
      var valorAtual = easeOut(progresso) * valorFinal;

      aplicarFormato(el, valorAtual);

      if (progresso < 1) {
        requestAnimationFrame(frame);
      } else {
        aplicarFormato(el, valorFinal); // garante valor exacto no fim
      }
    }

    requestAnimationFrame(frame);
  }

  // ── IntersectionObserver — só animar quando visível ──────────────────
  // (evita animar números que o utilizador nunca chegou a ver)

  function initCounters() {
    var counters = document.querySelectorAll('.counter[data-valor]');
    if (!counters.length) return;

    if ('IntersectionObserver' in window) {
      var observer = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            animarContador(entry.target);
            observer.unobserve(entry.target); // animar só uma vez
          }
        });
      }, { threshold: 0.2 });

      counters.forEach(function (el) { observer.observe(el); });
    } else {
      // Fallback para browsers sem IntersectionObserver
      counters.forEach(animarContador);
    }
  }

  // ── Inicializar ───────────────────────────────────────────────────────

  document.addEventListener('DOMContentLoaded', initCounters);

  // Expor formatadores globalmente (para uso noutros scripts se necessário)
  window.WasomFormat = {
    moeda:       formatarMoeda,
    porcentagem: formatarPorcentagem,
    decimal:     formatarDecimal,
    contagem:    formatarContagem
  };

})();